dashboard.definition:
{
	"title": "Scalable Network Segmentation",
	"description": "Connect segmentation posture, trust boundaries, and enforcement coverage at scale.",
	"inputs": {
		"input_time_range": {
			"options": {
				"defaultValue": "-24h@h,now",
				"token": "time_tok"
			},
			"title": "Time Range",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"visualizations": {
			"global": {
				"showLastUpdated": true,
				"showProgressBar": true
			}
		}
	},
	"visualizations": {
		"viz_header_bg": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "#1e293b",
				"strokeColor": "rgba(14,165,233,0.42)"
			}
		},
		"viz_header_icon": {
			"type": "splunk.image",
			"title": "Scalable Network Segmentation",
			"options": {
				"preserveAspectRatio": true,
				"src": "/static/app/splunk-cisco-dashboards/images/overview/secure-networking/segmentation.svg"
			}
		},
		"viz_header": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "transparent",
				"fontColor": "#f1f5f9",
				"markdown": "# Scalable Network Segmentation\nConnect segmentation posture, trust boundaries, and enforcement coverage at scale."
			}
		},
		"viz_seg_total_assignments": {
			"type": "splunk.singlevalue",
			"title": "Active SGT Assignments",
			"dataSources": {
				"primary": "ds_seg_total_assignments"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('total_assignments') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#0ea5e9"
			},
			"description": "Count of active SGT assignments observed in the selected time window from Cisco ISE authentication syslog, reflecting the number of distinct user/device classifications where a non-default Security Group Tag was…"
		},
		"viz_seg_unique_sgts": {
			"type": "splunk.singlevalue",
			"title": "Unique SGTs",
			"dataSources": {
				"primary": "ds_seg_unique_sgts"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('unique_sgts') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#0d9488"
			},
			"description": "Count of unique Security Group Tags actively in use across ISE authentication events, reflecting the breadth of TrustSec segmentation classification deployed in the environment."
		},
		"viz_seg_sgt_blocks": {
			"type": "splunk.singlevalue",
			"title": "SGT-Enforced Blocks",
			"dataSources": {
				"primary": "ds_seg_sgt_blocks_total"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('sgt_enforced_blocks') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#dc2626"
			},
			"description": "Total count of FMC block decisions where the source carried an active TrustSec SGT , serving as the primary Scalable Network Segmentation enforcement KPI for the Hybrid Mesh Firewalling overview."
		},
		"viz_seg_binding_mix": {
			"type": "splunk.pie",
			"title": "IP-SGT Binding Mix",
			"dataSources": {
				"primary": "ds_seg_ip_sgt_bindings"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "right",
				"seriesColors": [
					"#0ea5e9",
					"#16a34a",
					"#f59e0b",
					"#dc2626",
					"#8b5cf6"
				]
			},
			"description": "Shows the distribution of IP-to-SGT bindings across Security Group Tags, reporting how many bound IPs fall under each Security Group — the core \"SGT by Site/Device\" view for the Segmentation pillar."
		},
		"viz_seg_status_rollup": {
			"type": "splunk.table",
			"title": "Segmentation Status by Site",
			"dataSources": {
				"primary": "ds_seg_status_rollup"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Creates a segmentation adoption rollup by ISE site, comparing total authenticated endpoints to the subset carrying Security Group Tags."
		},
		"viz_seg_sgt_distribution": {
			"type": "splunk.table",
			"title": "SGT Distribution by Site and Device",
			"dataSources": {
				"primary": "ds_seg_sgt_distribution"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Breaks SGT-tagged authentications down by site, network device, and Security Group Tag for segmentation drilldowns."
		},
		"viz_seg_policy_hits": {
			"type": "splunk.bar",
			"title": "ISE Policy Hits by Network Device",
			"dataSources": {
				"primary": "ds_seg_policy_hits"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "off",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#8b5cf6"
				]
			},
			"description": "Ranks ISE policy-set hits by the network device (site/branch identity, e.g. wireless controller or firewall hostname) that triggered them — the closest real, validated proxy for \"Policy Hits by Site\" available today."
		},
		"viz_seg_trustsec_readiness": {
			"type": "splunk.bar",
			"title": "TrustSec Hardware Readiness",
			"dataSources": {
				"primary": "ds_seg_trustsec_readiness"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "off",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#0d9488"
				]
			},
			"description": "Rolls up managed devices by Device Family and exact Device Type (model) from Catalyst Center inventory — the baseline needed to determine TrustSec/SGT hardware readiness across the fleet."
		},
		"viz_seg_excessive_mac": {
			"type": "splunk.table",
			"title": "Excessive MACs per Wired Port",
			"dataSources": {
				"primary": "ds_seg_excessive_mac"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Ranks wired switch ports by the number of distinct MAC addresses that authenticated behind them — a NAC-deployment health check that surfaces ports with a hub, daisy-chained switch, or loop behind a single access port."
		},
		"viz_seg_ot_iot": {
			"type": "splunk.table",
			"title": "OT/IoT Device Visibility",
			"dataSources": {
				"primary": "ds_seg_ot_iot"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Inventories OT/IoT devices discovered by Cisco Cyber Vision , grouped by device type with device counts and average risk score — the Cisco-native operational-technology visibility layer for segmentation planning."
		},
		"viz_seg_router_feature_trend": {
			"type": "splunk.area",
			"title": "Router Segmentation Feature Event Trend",
			"dataSources": {
				"primary": "ds_seg_router_feature_trend"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#0d9488",
					"#2563eb",
					"#f59e0b",
					"#dc2626",
					"#8b5cf6"
				],
				"lineWidth": 2,
				"nullValueDisplay": "gaps"
			},
			"description": "Trends observed Cisco IOS VRF, VLAN, VXLAN, VPN, and SGT/TrustSec events over time."
		},
		"viz_seg_router_feature_evidence": {
			"type": "splunk.table",
			"title": "Router VRF, VLAN, VXLAN, VPN, and SGT Evidence",
			"dataSources": {
				"primary": "ds_seg_router_feature_evidence"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Shows Cisco router and switch telemetry containing VRF, 802.1Q VLAN subinterface, VXLAN/VNI, VPN, or SGT/TrustSec evidence by device."
		},
		"viz_design_context": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#1e293b",
				"fontColor": "#f1f5f9",
				"markdown": "**Audience:** Network security, identity, and TrustSec operations  •  **Sources:** Cisco ISE authentication, SGT, and IP-SGT binding telemetry  •  **Reading guide:** Read adoption breadth first, then investigate binding mix and site-level gaps.  •  **Freshness:** Uses the dashboard time range"
			}
		},
		"viz_design_section": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#1e293b",
				"fontColor": "#f1f5f9",
				"markdown": "### TrustSec posture\nRead adoption breadth first, then investigate binding mix and site-level gaps."
			}
		}
	},
	"dataSources": {
		"ds_seg_total_assignments": {
			"name": "Secure Networking chain - SGT assignment count",
			"options": {
				"ref": "secure_networking_sgt_total_assignments_count",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_seg_unique_sgts": {
			"name": "Secure Networking chain - unique SGT count",
			"options": {
				"ref": "secure_networking_sgt_unique_count",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_seg_sgt_blocks_total": {
			"name": "Secure Networking chain - SGT block count",
			"options": {
				"ref": "secure_networking_sgt_fmc_blocks_total_count",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_seg_ip_sgt_bindings": {
			"name": "Secure Networking - IP-SGT Bindings by Security Group",
			"options": {
				"ref": "secure_networking_ip_sgt_bindings_by_group",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_seg_status_rollup": {
			"name": "Secure Networking chain - segmentation status",
			"options": {
				"ref": "secure_networking_segmentation_status_rollup",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_seg_sgt_distribution": {
			"name": "Secure Networking chain - SGT distribution",
			"options": {
				"ref": "secure_networking_sgt_distribution_by_site_device",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_seg_policy_hits": {
			"name": "Secure Networking - ISE Policy Hits by Network Device",
			"options": {
				"ref": "secure_networking_ise_policy_hits_by_device",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_seg_trustsec_readiness": {
			"name": "Secure Networking - TrustSec Hardware Readiness",
			"options": {
				"ref": "secure_networking_trustsec_hardware_readiness",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_seg_excessive_mac": {
			"name": "Secure Networking - Excessive Unique MAC per Wired Port",
			"options": {
				"ref": "secure_networking_excessive_mac_per_port",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_seg_ot_iot": {
			"name": "Secure Networking - OT IoT Device Visibility",
			"options": {
				"ref": "secure_networking_ot_iot_device_visibility",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_seg_router_feature_trend": {
			"name": "Secure Networking - Router Segmentation Feature Event Trend",
			"options": {
				"ref": "secure_networking_router_segmentation_feature_trend",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_seg_router_feature_evidence": {
			"name": "Secure Networking - Router Segmentation Feature Evidence",
			"options": {
				"ref": "secure_networking_router_segmentation_feature_evidence",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		}
	},
	"layout": {
		"globalInputs": [
			"input_time_range"
		],
		"layoutDefinitions": {
			"layout_overview": {
				"options": {
					"backgroundColor": "#020617",
					"display": "auto-scale",
					"height": 1706,
					"width": 1440
				},
				"structure": [
					{
						"item": "viz_header_bg",
						"position": {
							"x": 20,
							"y": 0,
							"w": 1400,
							"h": 88
						},
						"type": "block"
					},
					{
						"item": "viz_header_icon",
						"position": {
							"x": 36,
							"y": 14,
							"w": 56,
							"h": 56
						},
						"type": "block"
					},
					{
						"item": "viz_header",
						"position": {
							"x": 108,
							"y": 4,
							"w": 1292,
							"h": 76
						},
						"type": "block"
					},
					{
						"item": "viz_design_context",
						"position": {
							"x": 20,
							"y": 100,
							"w": 1400,
							"h": 64
						},
						"type": "block"
					},
					{
						"item": "viz_design_section",
						"position": {
							"x": 20,
							"y": 176,
							"w": 1400,
							"h": 54
						},
						"type": "block"
					},
					{
						"item": "viz_seg_total_assignments",
						"position": {
							"x": 20,
							"y": 242,
							"w": 335,
							"h": 200
						},
						"type": "block"
					},
					{
						"item": "viz_seg_unique_sgts",
