							"x": 375,
							"y": 242,
							"w": 335,
							"h": 200
						},
						"type": "block"
					},
					{
						"item": "viz_seg_sgt_blocks",
						"position": {
							"x": 730,
							"y": 242,
							"w": 335,
							"h": 200
						},
						"type": "block"
					},
					{
						"item": "viz_seg_binding_mix",
						"position": {
							"x": 1085,
