							"w": 690,
							"h": 300
						},
						"type": "block"
					},
					{
						"item": "viz_seg_policy_hits",
						"position": {
							"x": 20,
							"y": 774,
							"w": 690,
							"h": 280
						},
						"type": "block"
					},
					{
						"item": "viz_seg_trustsec_readiness",
						"position": {
							"x": 730,
							"y": 774,
							"w": 690,
							"h": 280
						},
						"type": "block"
					},
					{
						"item": "viz_seg_excessive_mac",
						"position": {
