							"h": 300
						},
						"type": "block"
					},
					{
						"item": "viz_seg_ot_iot",
						"position": {
							"x": 730,
							"y": 1070,
							"w": 690,
							"h": 300
						},
						"type": "block"
					},
					{
						"item": "viz_seg_router_feature_trend",
						"position": {
							"x": 20,
							"y": 1386,
							"w": 690,
							"h": 280
						},
						"type": "block"
					},
					{
						"item": "viz_seg_router_feature_evidence",
						"position": {
							"x": 730,
							"y": 1386,
							"w": 690,
							"h": 300
						},
						"type": "block"
					}
				],
				"type": "absolute"
			}
		},
		"options": {
			"showTitleAndDescription": false,
			"submitButton": false,
			"submitOnDashboardLoad": true
		},
		"tabs": {
			"items": [
				{
					"label": "overview",
					"layoutId": "layout_overview"
				}
			]
		}
	},
	"applicationProperties": {
		"collapseNavigation": false,
		"hideEdit": false,
		"hideExport": false
	}
}
